'use strict';
// Aokana / Sprite Unity engine (.dat PRead archives + multi-language .bs5 scripts, #327).
// Each .dat archive begins with a 1024-byte header: entry count = sum of int32s[4..254] (32-bit wrap), TOC key at +212,
// path-table key at +92. TOC entries (16 bytes each) hold size, path offset, entry key and data offset; payload bytes are
// deciphered by dd(buf, key) using a 256-byte table generated by keyTable(key).
// Archives are layered as system.dat -> def/arcs.txt (patch.dat, adult.dat ...), later archives overriding earlier ones.
const fs = require('node:fs');
const path = require('node:path');
const kit = require('./kit.cjs');
const { stat } = require('./file-key.cjs');
const voiceRef = require('./voice-ref.cjs');

const KANA = /[ぁ-ゖァ-ヺ]/;
const MEDIA_DAT = /^(?:bg|bg2|bgm|evcg|evcg2|hevcg|hevcg2|sprites|sprites2|systemui|voice)\.dat$/i;
const AUDIO_ENTRY = /\.(?:ogg|opus|wav|mp3|m4a)$/i;
const HDR_SIZE = 1024;
const MAX_FILES = 200000;
const MAX_PATHS = 32 << 20;

function keyTable(k0) {
  k0 = k0 >>> 0;
  let a = (Math.imul(k0, 7391) + 42828) >>> 0;
  let c = ((a << 17) ^ a) >>> 0;
  const b = Buffer.allocUnsafe(256);
  for (let i = 0; i < 256; i++) {
    a = (a - k0 + c) >>> 0;
    c = (a + 56) >>> 0;
    a = Math.imul(a, c & 239) >>> 0;
    b[i] = a & 0xff;
    a = a >>> 1;
  }
  return b;
}

function decryptInPlace(buf, k0) {
  const key = keyTable(k0);
  for (let i = 0; i < buf.length; i++) {
    let v = buf[i];
    v = (v ^ key[i % 253]) & 0xff;
    v = (v + 3) & 0xff;
    v = (v + key[i % 89]) & 0xff;
    v = (v ^ 153) & 0xff;
    buf[i] = v;
  }
  return buf;
}

const listMemo = new Map();
function listArchive(file) {
  const key = file + '|' + stat(file);
  if (listMemo.has(key)) return listMemo.get(key);
  let out = null;
  try {
    const fileSize = fs.statSync(file).size;
    if (fileSize >= HDR_SIZE + 16) {
      const hdr = kit.readAt(file, 0, HDR_SIZE);
      if (hdr.length === HDR_SIZE) {
        let n = 0;
        for (let i = 4; i < 255; i++) n = (n + hdr.readInt32LE(i * 4)) | 0;
        if (n > 0 && n <= MAX_FILES && HDR_SIZE + 16 * n < fileSize) {
          const rtoc = decryptInPlace(kit.readAt(file, HDR_SIZE, 16 * n), hdr.readUInt32LE(212));
          const p0 = rtoc.readUInt32LE(12);
          const plen = p0 - (HDR_SIZE + 16 * n);
          if (plen > 0 && plen <= MAX_PATHS && p0 <= fileSize) {
            const rpaths = decryptInPlace(kit.readAt(file, HDR_SIZE + 16 * n, plen), hdr.readUInt32LE(92));
            const entries = [];
            let valid = true;
            for (let i = 0; i < n; i++) {
              const b = i * 16;
              const size = rtoc.readUInt32LE(b);
              const pathOff = rtoc.readUInt32LE(b + 4);
              const eKey = rtoc.readUInt32LE(b + 8);
              const offset = rtoc.readUInt32LE(b + 12);
              if (pathOff >= rpaths.length || offset < p0 || offset + size > fileSize) {
                valid = false;
                break;
              }
              let end = pathOff;
              while (end < rpaths.length && rpaths[end] !== 0) end++;
              if (end === pathOff) {
                valid = false;
                break;
              }
              entries.push({
                name: rpaths.toString('ascii', pathOff, end).toLowerCase(),
                size,
                offset,
                key: eKey,
              });
            }
            if (valid) out = entries;
          }
        }
      }
    }
  } catch {
    out = null;
  }
  listMemo.set(key, out);
  if (listMemo.size > 16) listMemo.delete(listMemo.keys().next().value);
  return out;
}

function readEntry(file, entry) {
  return decryptInPlace(kit.readAt(file, entry.offset, entry.size), entry.key);
}

function dataDir(dir) {
  try {
    if (fs.existsSync(path.join(dir, 'system.dat'))) return dir;
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (e.isDirectory() && /_Data$/i.test(e.name)) {
        const sub = path.join(dir, e.name);
        if (fs.existsSync(path.join(sub, 'system.dat'))) return sub;
      }
    }
  } catch {}
  return '';
}

function probe(dir) {
  const d = dataDir(dir);
  if (!d) return false;
  const entries = listArchive(path.join(d, 'system.dat'));
  return !!entries && entries.some(e => /^scripts\/.*\.bs5$/i.test(e.name));
}

function scriptArchives(dir) {
  const d = dataDir(dir);
  if (!d) return [];
  const sysPath = path.join(d, 'system.dat');
  const sysEntries = listArchive(sysPath);
  if (!sysEntries) return [];

  const order = [sysPath];
  const seen = new Set([sysPath.toLowerCase()]);
  const add = name => {
    if (!name || MEDIA_DAT.test(name)) return;
    const full = path.join(d, name);
    const low = full.toLowerCase();
    if (seen.has(low) || !fs.existsSync(full)) return;
    seen.add(low);
    order.push(full);
  };

  const arcsEntry = sysEntries.find(e => e.name === 'def/arcs.txt');
  if (arcsEntry) {
    const arcsText = readEntry(sysPath, arcsEntry).toString('utf8');
    for (const raw of arcsText.split(/\r?\n/)) add(raw.trim());
  }
  try {
    for (const n of fs.readdirSync(d).sort()) {
      if (/^(?:patch|adult).*\.dat$/i.test(n)) add(n);
    }
  } catch {}
  return order;
}

function mergedEntries(dir) {
  const files = scriptArchives(dir);
  if (!files.length) return { files: [], map: new Map() };
  const map = new Map();
  for (const file of files) {
    const list = listArchive(file);
    if (!list) continue;
    for (const entry of list) map.set(entry.name, { file, entry });
  }
  return { files, map };
}

function scenes(dir) {
  const { map } = mergedEntries(dir);
  if (!map.size) return [];
  const merge = [], fallback = [];
  for (const [name, item] of map) {
    if (!/^scripts\/.*\.bs5$/i.test(name)) continue;
    if (/^scripts\/merge\//i.test(name)) merge.push(item);
    else if (!/^scripts\/(?:main|logo|replay|hreplay_.*)\.bs5$/i.test(name)) fallback.push(item);
  }
  const picked = merge.length ? merge : fallback;
  return picked
    .map(item => ({
      name: item.entry.name.replace(/^scripts\/(?:merge|jp)\//i, '').replace(/^scripts\//i, ''),
      read: () => readEntry(item.file, item.entry),
    }))
    .sort((a, b) => a.name.localeCompare(b.name));
}

function stripComment(s) {
  const i = s.indexOf('//');
  return i > 0 ? s.slice(0, i) : s;
}

function cleanText(s) {
  return stripComment(String(s || ''))
    .replace(/<T\s+\d+>/gi, '')
    .replace(/\\n/g, '\n')
    .replace(/<\/?(?:color|size|i|b)(?:=[^>]*)?>/gi, '');
}

// Mirrors ScriptAokana::DoText: optional 【speaker】：prefix, inline // comment trim, leading U+3000 strip.
function splitSlot(raw) {
  let s = String(raw || '');
  let speaker = '';
  let idx = 0;
  if (s.startsWith('【')) {
    const close = s.indexOf('】');
    if (close >= 1) {
      speaker = s.slice(1, close);
      idx = close + 1;
    }
  }
  if (s[idx] === '：') idx++;
  while (s[idx] === '\t') idx++;
  let body = s.slice(idx);
  body = stripComment(body);
  if (body.startsWith('\u3000')) body = body.slice(1);
  return { speaker, text: cleanText(body) };
}

function parseSelectSlot(slot) {
  const items = new Map();
  const s = stripComment(String(slot || ''));
  for (const m of s.matchAll(/\b(\d+|OUTLINE):"((?:[^"\\]|\\.)*)"/g)) {
    let val = m[2];
    if (m[1] === 'OUTLINE' && val.startsWith('【')) {
      const end = val.indexOf('】');
      if (end >= 0) val = val.slice(end + 1);
    }
    items.set(m[1], cleanText(val));
  }
  return items;
}

function pickSlots(slots) {
  if (slots.length >= 3 || (slots.length === 2 && !KANA.test(slots[0]) && KANA.test(slots[1]))) {
    return { en: slots[0] || '', jp: slots[1] || '', cn: slots[2] || '', tc: slots[3] || '' };
  }
  if (slots.length === 2) return { en: '', jp: slots[0] || '', cn: slots[1] || '', tc: '' };
  return { en: '', jp: slots[0] || '', cn: '', tc: '' };
}

function parseRows(buf) {
  let text = buf.toString('utf8');
  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
  const rows = [];
  const vt = voiceRef.tracker();

  for (const raw of text.split(/\r?\n/)) {
    const trimmed = raw.trim();
    if (!trimmed || trimmed.startsWith('//')) continue;

    const cmd = stripComment(trimmed).trim();
    const vm = /^voice[01]\s+(\S+)/i.exec(cmd);
    if (vm) {
      const v = voiceRef.clean(vm[1]);
      if (v) vt.set(v);
      else if (/^(?:stop|fadeout)$/i.test(vm[1])) vt.take();
      continue;
    }

    if (raw[0] === '\u2402') {
      const s = pickSlots(raw.slice(1).split('\u2402'));
      const jp = splitSlot(s.jp);
      const voice = vt.take();
      if (!jp.text || jp.text === '@delete') continue;
      const cn = s.cn ? splitSlot(s.cn) : { text: '' };
      const tc = s.tc ? splitSlot(s.tc) : { text: '' };
      const en = s.en ? splitSlot(s.en) : { text: '' };
      const zh = (cn.text && cn.text !== '@delete') ? cn.text : (tc.text && tc.text !== '@delete' ? tc.text : '');
      rows.push({
        ja: jp.text,
        zh,
        en: en.text && en.text !== '@delete' ? en.text : '',
        tc: tc.text && tc.text !== '@delete' ? tc.text : '',
        speaker: jp.speaker,
        voice,
      });
      continue;
    }

    if (raw[0] === '\u2405') {
      vt.take();
      const s = pickSlots(raw.slice(1).split('\u2405'));
      const jpItems = parseSelectSlot(s.jp);
      const cnItems = parseSelectSlot(s.cn || s.tc);
      const tcItems = parseSelectSlot(s.tc);
      const enItems = parseSelectSlot(s.en);
      const order = [...jpItems.keys()].sort((a, b) => (a === 'OUTLINE' ? -1 : b === 'OUTLINE' ? 1 : Number(a) - Number(b)));
      for (const k of order) {
        const ja = jpItems.get(k);
        if (!ja) continue;
        rows.push({
          ja,
          zh: cnItems.get(k) || tcItems.get(k) || '',
          en: enItems.get(k) || '',
          tc: tcItems.get(k) || '',
          speaker: '',
          voice: null,
        });
      }
      continue;
    }

    if (/^(?:[^\x00-\x7f]|<)/.test(trimmed) && !trimmed.includes('@delete')) {
      const p = splitSlot(raw.trimStart());
      const voice = vt.take();
      if (p.text) rows.push({ ja: p.text, zh: '', en: '', tc: '', speaker: p.speaker, voice });
    }
  }
  return rows;
}

function parse(buf) {
  const rows = parseRows(buf);
  const lines = [];
  const zh = [];
  const speakers = [];
  const voices = [];
  for (const r of rows) {
    lines.push(r.ja);
    zh.push(r.zh);
    speakers.push(r.speaker);
    voices.push(r.voice);
  }
  const v = voiceRef.keep(voices);
  return v ? { lines, anchors: [], zh, speakers, voices: v } : { lines, anchors: [], zh, speakers };
}

function patchLines(base) {
  let any = false;
  const list = base.map(scene => {
    const zh = scene.zh || [];
    if (!zh.some(Boolean)) return scene;
    any = true;
    return { ...scene, patched: true, lines: scene.lines.map((t, k) => zh[k] || t) };
  });
  return any ? list : null;
}

function foreign(dir) {
  const key = require('../original-text.cjs').foreignKey;
  const out = new Map();
  const seq = [];
  out.seq = seq;
  const parsed = [];
  for (const s of scenes(dir)) {
    try {
      parsed.push(parseRows(s.read()));
    } catch {}
  }
  for (const field of ['zh', 'tc', 'en']) {
    for (const rows of parsed) {
      for (const r of rows) {
        const alt = r[field];
        if (!r.ja || !alt) continue;
        const k = key(alt);
        if (k.length < 2) continue;
        seq.push([k, r.ja, alt]);
        if (!out.has(k)) out.set(k, r.ja);
      }
    }
  }
  return out;
}

function audio(file) {
  const entries = listArchive(file);
  if (!entries) return null;
  const clips = entries.filter(e => AUDIO_ENTRY.test(e.name));
  if (!clips.length) return null;
  return clips.map(e => ({ name: e.name, read: () => readEntry(file, e) }));
}

const engine = {
  id: 'aokana',
  hint: '<游戏>_Data\\system.dat（PRead .dat + .bs5）',
  scenes,
  archives: () => [],
  sources: dir => mergedEntries(dir).files,
  parse,
  test: () => false,
  patchLines,
  foreign,
};

module.exports = {
  engine,
  probe,
  listArchive,
  readEntry,
  audio,
  _internal: { keyTable, decryptInPlace, parseRows, splitSlot, cleanText },
};
